import json
d=json.load(open('docs/audits/audit-20261011-054325-accuknox-help.json',encoding='utf-8'))
def find(o,key,path=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if k==key: yield path+'/'+k,v
            yield from find(v,key,path+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): yield from find(v,key,path+f'[{i}]')
for p,v in find(d,'areas'):
    if isinstance(v,list): print(p,len(v),[ (a.get('single'),[o['p'] for o in a.get('owners',[])]) for a in v])
for key in ['tasks','next','board','todo']:
    for p,v in find(d,key):
        if isinstance(v,list) and v and isinstance(v[0],dict): print(p,len(v),[t.get('owner',t.get('suggested_owner',t.get('who'))) for t in v])
print([k for k in d.keys()])
EOF

